mapper.update:

UPDATE ch_post
SET post_view_number = post_view_number + #{delta}
WHERE post_id = #{postId}


UPDATE ch_post
SET post_like_number = GREATEST(post_like_number + #{delta}, 0)
WHERE post_id = #{postId}


UPDATE ch_post
SET post_collect_number = GREATEST(post_collect_number + #{delta}, 0)
WHERE post_id = #{postId}
